import{z as n,x as i,o as e,c as D,q as l,j as t,D as B,d as o,s as A,S as r,b as E}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"Tomasulo","description":"","frontmatter":{"title":"Tomasulo","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/tomasulo.md","filePath":"cs/tomasulo.md","lastUpdated":1791063341000}'),m={name:"cs/tomasulo.md"};function p(d,a,u,C,T,f){const s=i("Mermaid");return e(),D("div",null,[a[2]||(a[2]=l('<h1 id="tomasulo" tabindex="-1">Tomasulo <a class="header-anchor" href="#tomasulo" aria-label="Permalink to &quot;Tomasulo&quot;">​</a></h1><div class="epigraph"><p>保留站记下谁在等哪次运算的结果，公共数据总线一广播标签，等待者自己抓住数据。</p><footer>—— 据 Tomasulo, An Efficient Algorithm for Exploiting Multiple Arithmetic Units, IBM Journal 1967 整理</footer></div><p><a href="/cs/ooo-rob">上一课</a>规定了 ROB 与按序提交，并把重命名说成「必须有」。本课不重讲提交纪律。缺口是：还没有一套具体的唤醒与分发机制，让「操作数就绪」变成硬件能做的比较。本课只讲 Tomasulo：保留站、标签、CDB。IBM System/360 Model 91 的浮点单元是原文场景；整数乱序核沿用同一思想。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>ROB 知道指令完成没有，但功能单元怎么发现操作数到了？轮询架构寄存器不够：值可能还在另一单元的输出上，且寄存器已被重命名。缺口不是再加一个提交点，而是<strong>用标签代替寄存器名做数据流握手</strong>。</p><p>Tomasulo 原论文为多运算单元与长延迟浮点而写，尚未画现代 ROB；教学上把保留站与 ROB 叠在一起：站负责执行，ROB 负责精确状态。</p><p><span class="marginnote">术语翻译：「数据流握手」就是指令不看排在第几，只问「我要的数到了没」。标签是那张取货单——寄存器名被重命名成标签，谁广播的货单号对上，谁就把数抓走。</span></p><p><span class="marginnote">1967 年的 CDB 是广播总线。当代核用点对点与唤醒矩阵，语义仍是「标签匹配则抓数据」。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>每条已发射未执行的指令占用一个保留站：存操作码、操作数或「等待的标签」、目标标签。寄存器状态表指出：该架构寄存器的当前生产者是哪一个标签（或值已在寄存器）。运算完成，结果带标签上 CDB；所有站比较标签，匹配则写入操作数并可能变为就绪。</p>',10)),(e(),t(r,null,{default:B(()=>[A(s,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20IS%5B%22%E5%8F%91%E5%B0%84%E5%88%B0%E4%BF%9D%E7%95%99%E7%AB%99%22%5D%20--%3E%20WAIT%5B%22%E7%AD%89%E6%A0%87%E7%AD%BE%E6%88%96%E5%B7%B2%E6%9C%89%E5%80%BC%22%5D%0A%20%20WAIT%20--%3E%20EX%5B%22%E4%B8%A4%E6%93%8D%E4%BD%9C%E6%95%B0%E9%BD%90%E5%88%99%E8%BF%90%E7%AE%97%22%5D%0A%20%20EX%20--%3E%20CDB%5B%22CDB%20%E5%B9%BF%E6%92%AD%E7%BB%93%E6%9E%9C%2B%E6%A0%87%E7%AD%BE%22%5D%0A%20%20CDB%20--%3E%20WAIT%0A%20%20CDB%20--%3E%20RF%5B%22%E5%86%99%E5%AF%84%E5%AD%98%E5%99%A8%2FROB%22%5D%0A"})]),fallback:B(()=>[...a[0]||(a[0]=[o(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,"load/store 另有地址序约束，原文用缓冲。本课只要求：RAW 靠标签，WAR/WAW 靠「后来的发射改状态表指向新标签」，旧站仍拿旧标签。",-1)),a[4]||(a[4]=E("h2",{id:"机制",tabindex:"-1"},[o("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=E("p",null,[o("这就是数据流：指令不按程序序被挑选，按操作数齐被挑选。与 ROB 结合后，CDB 写 ROB 项，提交仍按头指针。"),E("a",{href:"/cs/superscalar-issue"},"超标量发射"),o("的宽度变成每拍能填几个站、CDB 能广播几次。")],-1)),a[6]||(a[6]=E("p",null,"精确异常：冲刷时作废站与标签，状态表回到 ROB 头对应的映射。Tomasulo 原文更关心吞吐而非陷阱；当代实现把两者接上。",-1)),(e(),t(r,null,{default:B(()=>[A(s,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20I1%5B%22I1%3A%20%E4%B9%98%E6%B3%95%2C%E7%9B%AE%E6%A0%87%E6%A0%87%E7%AD%BE%20T1%22%5D%20--%3E%20A%5B%22%E5%8D%A0%E7%94%A8%E4%BF%9D%E7%95%99%E7%AB%99%20A%22%5D%0A%20%20I2%5B%22I2%3A%20%E5%8A%A0%E6%B3%95%2C%E6%BA%90%E6%93%8D%E4%BD%9C%E6%95%B0%E7%AD%89%E5%BE%85%20T1%22%5D%20--%3E%20B%5B%22%E5%8D%A0%E7%94%A8%E4%BF%9D%E7%95%99%E7%AB%99%20B%2C%E8%AE%B0%E4%B8%8B%20T1%22%5D%0A%20%20A%20--%3E%20EX%5B%22A%20%E5%AE%8C%E6%88%90%E8%BF%90%E7%AE%97%22%5D%0A%20%20EX%20--%3E%20CDB%5B%22CDB%20%E5%B9%BF%E6%92%AD%20T1%20%E4%B8%8E%E7%BB%93%E6%9E%9C%22%5D%0A%20%20CDB%20--%3E%20M%7B%22B%20%E6%AF%94%E5%AF%B9%E8%87%AA%E5%B7%B1%E7%9A%84%E6%A0%87%E7%AD%BE%22%7D%0A%20%20M%20--%3E%7C%22%E5%8C%B9%E9%85%8D%20T1%22%7C%20RDY%5B%22%E6%93%8D%E4%BD%9C%E6%95%B0%E5%B0%B1%E7%BB%AA%2C%E8%BF%9B%E5%85%A5%E6%89%A7%E8%A1%8C%22%5D%0A%20%20M%20--%3E%7C%22%E4%B8%8D%E5%8C%B9%E9%85%8D%22%7C%20KEEP%5B%22%E5%85%B6%E4%BB%96%E7%AB%99%E7%BB%A7%E7%BB%AD%E7%AD%89%E5%90%84%E8%87%AA%E7%9A%84%E6%A0%87%E7%AD%BE%22%5D%0A"})]),fallback:B(()=>[...a[1]||(a[1]=[o(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=l('<p><span class="marginnote">数字实例：浮点乘法 4 拍、加法 2 拍时，依赖乘法结果的加法不必堵在发射口傻等——它发射时就挂进保留站，第 4 拍 CDB 一广播、第 5 拍即可执行。等待被搬进了保留站，而不是占着前端。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把记分牌当成另一套主干：记分牌跟踪忙位但不做标签重命名，WAW 要停。也不引入负载值预测。SIMD 与多核不在本课；Tomasulo 解决的是单核 ILP 的唤醒。</p><p>后课默认：谈到乱序唤醒，就是标签匹配。下一条路是数据级并行：一条指令吃一个向量。</p><p><span class="marginnote">常见误区：把 Tomasulo 与记分牌混为一谈。记分牌也乱序执行，但寄存器名不重命名，WAW/WAR 仍要停下来等；Tomasulo 的标签重命名把这两类假相关一并消掉——这是两代机制的差别。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>保留站 + 标签 + CDB：就绪即执行，RAW 靠匹配。</li><li>与 ROB 叠放才有精确提交。</li><li>向量/SIMD 是另一轴并行，下一课才走。</li><li>出处：Tomasulo, <em>IBM Journal of Research and Development</em>, 1967；Hennessy and Patterson, <em>CA:AQA</em>。</li></ul>',7))])}const _=n(m,[["render",p]]);export{c as __pageData,_ as default};
